  containerId?: string;

  /**
   * Whether to pause auto-dismiss on hover
   * @default true
   */
  pauseOnHover?: boolean;

  /**
   * Whether to pause auto-dismiss when the browser tab loses focus
   * @default true
   */
  pauseOnFocusLoss?: boolean;

  /**
   * Keyboard hotkey to focus the toast notification region
   * @default 'F8'
   */
  hotkey?: string;
}

/**
 * Toast context value for useToast hook
 */
export interface ToastContextValue {
  /**
   * Show a success toast
   */
  success: (message: ReactNode, options?: ToastOptions) => string;

  /**
   * Show an error toast
   */
  error: (message: ReactNode, options?: ToastOptions) => string;

  /**
   * Show a warning toast
   */
  warning: (message: ReactNode, options?: ToastOptions) => string;

  /**
   * Show an info toast
   */
  info: (message: ReactNode, options?: ToastOptions) => string;

  /**
   * Show a default toast
   */
  toast: (message: ReactNode, options?: ToastOptions) => string;

  /**
   * Dismiss a specific toast by ID
   */
  dismiss: (id: string) => void;

  /**
   * Dismiss all toasts
   */
  dismissAll: () => void;

  /**
   * Update an existing toast
